// src/components/StandardLogPanel.js  
class StandardLogPanel {
    constructor(container, options = {}) {
        this.container = container;
        this.maxLines = options.maxLines || 200;
        this._createSimpleUI();
    }

    // 简化UI创建
    _createSimpleUI() {
        this.container.innerHTML = `
            <div class="log-panel">
                <div class="log-header">
                    <span>系统日志</span>
                    <button onclick="this.clear()">清空</button>
                    <button onclick="this.toggle()">折叠</button>
                </div>
                <div class="log-body"></div>
            </div>
        `;
    }

    // 核心方法：添加日志
    append(level, message) {
        const body = this.container.querySelector('.log-body');
        const line = `[${new Date().toLocaleTimeString()}] [${level}] ${message}`;

        body.textContent += (body.textContent ? '\n' : '') + line;

        // 简单的行数限制
        const lines = body.textContent.split('\n');
        if (lines.length > this.maxLines) {
            body.textContent = lines.slice(-this.maxLines).join('\n');
        }

        // 自动滚动
        body.scrollTop = body.scrollHeight;
    }

    // 标准嵌入方法
    static embed(selector, options) {
        const container = document.querySelector(selector);
        return new StandardLogPanel(container, options);
    }
}
```

#### 3. 错误回溯器（ErrorBacktracer）
```javascript
// src/core/ErrorBacktracer.js
class ErrorBacktracer {
    constructor() {
        this.errors = [];
        this._setupEssentialHandlers();
    }

    // 只设置必要的错误处理器
    _setupEssentialHandlers() {
        // 1. 同步错误（最重要）
        window.addEventListener('error', (e) => {
            this._recordError('SYNC_ERROR', e.error, {
                filename: e.filename,
                lineno: e.lineno,
                colno: e.colno
            });
        });

        // 2. 异步错误（次重要）
        window.addEventListener('unhandledrejection', (e) => {
            this._recordError('ASYNC_ERROR', e.reason);
        });
    }

    // 简化错误记录
    _recordError(type, error, context = {}) {
        const errorEntry = {
            type,
            message: error?.message || String(error),
            stack: error?.stack,
            timestamp: new Date().toISOString(),
            context
        };

        this.errors.push(errorEntry);

        // 重要错误持久化
        if (type === 'SYNC_ERROR') {
            this._persistCriticalError(errorEntry);
        }
    }

    // 简单查询
    queryErrors(since = null) {
        let results = this.errors;
        if (since) {
            results = results.filter(e => new Date(e.timestamp) >= new Date(since));
        }
        return results;
    }
}
```

